# Build «الطائر الذهبي» (GoldenBird.exe). Generated by forge\make_white_bird.py — edit the forge, not this file.
#   0) runs the smoke tests (..\tests\run_tests.ps1) and stops on any failure; -SkipTests skips them
#   1) stamps ui\version.txt (the app compares it with the staged build and offers «حدّث دلوقتي»)
#   2) builds into %USERPROFILE%\.goldenbird-build\dist_new, then stages it in ...\dist (never a half-built folder)
#   3) installs to %USERPROFILE%\GoldenBird unless that copy is running (then its update button does it)
#   4) (re)creates the Desktop shortcut «الطائر الذهبي» -> %USERPROFILE%\GoldenBird\GoldenBird.exe on every build
# Not in AppData on purpose: a build started from a session inside Claude Desktop gets AppData writes redirected into
# Claude's package cache, which Explorer can't see (the shortcut then breaks). It never touches the Black Dragon.
param([switch]$SkipTests)          # -SkipTests: build without running the smoke tests first
$ErrorActionPreference = "Continue"
if ($SkipTests) {
  Write-Output "tests skipped (-SkipTests)"
} else {
  $tests = [IO.Path]::GetFullPath((Join-Path $PSScriptRoot "..\tests\run_tests.ps1"))
  if (-not (Test-Path -LiteralPath $tests)) { Write-Output "build stopped: test runner not found: $tests (-SkipTests builds anyway)"; exit 1 }
  powershell -NoProfile -ExecutionPolicy Bypass -File $tests
  if ($LASTEXITCODE -ne 0) { Write-Output "build stopped: tests failed (exit $LASTEXITCODE), nothing was built (-SkipTests builds anyway)"; exit 1 }
}
$here = Split-Path -Parent $MyInvocation.MyCommand.Path
$work = Join-Path $env:USERPROFILE ".goldenbird-build"
Set-Location $here
(Get-Date -Format "yyyy.MM.dd-HHmm") | Set-Content -Encoding ascii (Join-Path $here "ui\version.txt")
Remove-Item -Recurse -Force (Join-Path $here "__pycache__") -ErrorAction SilentlyContinue
python -m PyInstaller --noconfirm --windowed --name GoldenBird --icon "$here\ui\golden-bird.ico" `
  --add-data "$here\ui;ui" --add-data "$here\chrome_extension;chrome_extension" --add-data "$here\mcp_control.py;." --add-data "$here\voice.py;." --add-data "$here\golden;golden" `
  --hidden-import keyring.backends.Windows --hidden-import webview.dom --hidden-import control --hidden-import golden_tools --hidden-import golden_steer `
  --distpath "$work\dist_new" --workpath "$work\build" --specpath $work app.py
if ($LASTEXITCODE -ne 0) { throw "PyInstaller failed" }
robocopy "$work\dist_new\GoldenBird" "$work\dist\GoldenBird" /MIR /NFL /NDL /NJH /NJS /NP | Out-Null
$dst = Join-Path $env:USERPROFILE "GoldenBird"
$exe = Join-Path $dst "GoldenBird.exe"
if (Get-Process GoldenBird -ErrorAction SilentlyContinue | Where-Object { $_.Path -eq $exe }) {
  Write-Output "staged (app is open: use the update button inside the app)"
} else {
  New-Item -ItemType Directory -Force $dst | Out-Null
  robocopy "$work\dist\GoldenBird\_internal" "$dst\_internal" /MIR /NFL /NDL /NJH /NJS /NP | Out-Null
  Copy-Item "$work\dist\GoldenBird\GoldenBird.exe" $exe -Force
  Write-Output "installed: $exe"
}
$desk = [Environment]::GetFolderPath("Desktop")
$lnkPath = Join-Path $desk ((-join [char[]](0x627,0x644,0x637,0x627,0x626,0x631,0x20,0x627,0x644,0x630,0x647,0x628,0x64a)) + ".lnk")
if (Test-Path -LiteralPath $exe) {
  $ws = New-Object -ComObject WScript.Shell
  $lnk = $ws.CreateShortcut("$desk\GoldenBird.lnk")
  $lnk.TargetPath = $exe; $lnk.WorkingDirectory = $dst; $lnk.IconLocation = "$exe,0"; $lnk.Description = "Golden Bird"; $lnk.Save()
  Move-Item -LiteralPath "$desk\GoldenBird.lnk" -Destination $lnkPath -Force
  Write-Output "shortcut: $lnkPath -> $exe"
}
